function a(e){return`₹${e.toLocaleString("en-IN")}`}function g(e){switch(e){case"single":return"Single";case"double":return"2-Sharing";case"triple":return"3-Sharing";case"quad":return"4+ Sharing";default:return e}}function i(e){return e.split(" ").map(r=>r[0]).join("").toUpperCase().slice(0,2)}function o(e){const r=["bg-brand-500","bg-purple-500","bg-pink-500","bg-teal-500","bg-orange-500","bg-cyan-500","bg-indigo-500","bg-emerald-500"];let t=0;for(let n=0;n<e.length;n++)t=e.charCodeAt(n)+((t<<5)-t);return r[Math.abs(t)%r.length]}export{i as a,o as b,a as f,g};
